from rdkit import Chem
from rdkit.Chem import AllChem, rdChemReactions

# --- Inputs ---
reactant_smiles_list = [
    "CCO",           # ethanol
    "CC(=O)Cl",      # acetyl chloride
    "c1ccccc1O",     # phenol
    "bad_smiles!!",  # invalid
]

reaction_smarts = "[OH:1].[C:2](=O)Cl>>[C:2](=O)[O:1]"  # esterification

# --- Parse reaction ---
rxn = rdChemReactions.ReactionFromSmarts(reaction_smarts)
if rxn is None:
    raise ValueError("Failed to parse reaction SMARTS.")

rxn.Initialize()

# --- Check atom-mapping assumptions ---
def check_atom_mapping(rxn):
    issues = []
    rct_maps = set()
    for rct in rxn.GetReactants():
        for atom in rct.GetAtoms():
            m = atom.GetAtomMapNum()
            if m:
                if m in rct_maps:
                    issues.append(f"Duplicate reactant atom map {m}")
                rct_maps.add(m)
    prod_maps = set()
    for prod in rxn.GetProducts():
        for atom in prod.GetAtoms():
            m = atom.GetAtomMapNum()
            if m:
                if m in prod_maps:
                    issues.append(f"Duplicate product atom map {m}")
                prod_maps.add(m)
    unmapped_in_products = prod_maps - rct_maps
    if unmapped_in_products:
        issues.append(f"Product atom maps with no reactant counterpart: {unmapped_in_products}")
    return issues

mapping_issues = check_atom_mapping(rxn)
if mapping_issues:
    print("Atom-mapping issues:")
    for issue in mapping_issues:
        print(f"  - {issue}")
else:
    print("Atom-mapping: OK")

# --- Parse and validate reactants ---
n_reactant_templates = rxn.GetNumReactantTemplates()
print(f"\nReaction expects {n_reactant_templates} reactant(s).")

parsed, failed = [], []
for smi in reactant_smiles_list:
    mol = Chem.MolFromSmiles(smi)
    if mol is None:
        failed.append(smi)
    else:
        parsed.append((smi, mol))

print(f"\nReactant parse: {len(parsed)} OK, {len(failed)} failed.")
if failed:
    print("  Failed SMILES:", failed)

# --- Run reaction over all pairs (or single reactants) ---
# Build tuples matching the number of reactant templates.
# For a 2-reactant reaction, try all ordered pairs of valid mols.
from itertools import permutations

seen_products: set[str] = set()
product_records: list[dict] = []

reactant_mols = [mol for _, mol in parsed]

if n_reactant_templates == 1:
    combos = [(mol,) for mol in reactant_mols]
elif n_reactant_templates == 2:
    combos = list(permutations(reactant_mols, 2))
else:
    raise NotImplementedError(f"Adjust combo generation for {n_reactant_templates} reactants.")

for combo in combos:
    try:
        product_sets = rxn.RunReactants(combo)
    except Exception as e:
        print(f"  RunReactants error for {[Chem.MolToSmiles(m) for m in combo]}: {e}")
        continue

    for products in product_sets:
        for prod_mol in products:
            try:
                Chem.SanitizeMol(prod_mol)
            except Exception as e:
                reactant_smis = [Chem.MolToSmiles(m) for m in combo]
                print(f"  Sanitization failed for product from {reactant_smis}: {e}")
                continue

            canon = Chem.MolToSmiles(prod_mol)
            if canon not in seen_products:
                seen_products.add(canon)
                product_records.append({
                    "product_smiles": canon,
                    "reactants": [Chem.MolToSmiles(m) for m in combo],
                })

# --- Report ---
print(f"\nUnique valid products: {len(product_records)}")
for rec in product_records:
    print(f"  {rec['product_smiles']}  <-  {rec['reactants']}")
```

**Key design decisions:**

| Decision | Rationale |
|---|---|
| `rxn.Initialize()` before running | Ensures template matching is set up; avoids silent failures |
| Explicit `SanitizeMol` on products | `RunReactants` returns unsanitized mols by design — sanitize before any downstream use |
| Deduplicate on canonical SMILES | `MolToSmiles` canonicalizes, so equivalent representations collapse |
| Atom-map check before running | Maps that appear in products but not reactants indicate broken transforms (atoms created from nothing) |
| `permutations` for 2-reactant reactions | Reaction templates are ordered; A+B and B+A may both be valid reactant orderings |

**Checks reported:**
- **Invalid reactants**: `MolFromSmiles` returning `None`
- **Atom-mapping issues**: unmapped product atoms, duplicate map numbers
- **Sanitization failures**: products that don't pass RDKit's chemistry validation after the transform
